/* design-system.css — tokens das páginas server-rendered, no tema claro da loja (papéis M3). */
:root {
  /* cores */
  --color-bg:          #fcfbff;
  --color-surface:     #ffffff;
  --color-surface-2:   #f4f2fc;
  --color-border:      #dcd8eb;
  --color-ink:         #1b1a27;
  --color-ink-2:       #4b4861;
  --color-accent:      #6d5cff;
  --color-accent-h:    #5743e0;
  --color-success:     #13824b;
  --color-warning:     #b7791f;
  --color-danger:      #c62f4a;
  --color-info:        #0b6aa2;

  /* tipografia */
  --font-sans: "Segoe UI Variable Text", "SF Pro Text", -apple-system, system-ui, Roboto, "Helvetica Neue", sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", monospace;
  --text-xs:   0.75rem;
  --text-sm:   0.875rem;
  --text-base: 1rem;
  --text-lg:   1.125rem;
  --text-xl:   1.25rem;
  --text-2xl:  1.5rem;
  --text-3xl:  1.875rem;
  --text-4xl:  2.25rem;
  --fw-normal: 400;
  --fw-medium: 500;
  --fw-bold:   700;
  --fw-black:  900;
  --lh-tight:  1.25;
  --lh-normal: 1.5;
  --lh-loose:  1.75;

  /* espaçamento (base 4px) */
  --sp-1:  4px;
  --sp-2:  8px;
  --sp-3:  12px;
  --sp-4:  16px;
  --sp-5:  20px;
  --sp-6:  24px;
  --sp-8:  32px;
  --sp-10: 40px;
  --sp-12: 48px;
  --sp-16: 64px;

  /* raios */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-full: 9999px;

  /* sombras */
  --shadow-sm: 0 1px 2px rgba(27,20,80,.08), 0 1px 3px 1px rgba(27,20,80,.05);
  --shadow-md: 0 1px 2px rgba(27,20,80,.08), 0 3px 8px 2px rgba(27,20,80,.07);
  --shadow-lg: 0 4px 10px rgba(27,20,80,.09), 0 10px 24px 4px rgba(27,20,80,.08);
  --shadow-accent: 0 6px 18px rgba(109,92,255,.32);

  /* transições */
  --ease-out: cubic-bezier(.16,1,.3,1);
  --dur-fast: 150ms;
  --dur-base: 250ms;

  /* layout */
  --max-w: 1100px;
  --content-w: 720px;
}

/* reset mínimo */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; }
body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: var(--lh-normal);
  background: var(--color-bg);
  color: var(--color-ink);
  -webkit-font-smoothing: antialiased;
}
img, video { display: block; max-width: 100%; }
a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }
input, button, textarea, select { font: inherit; }
ul, ol { list-style: none; }

/* utilities */
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
